local({
  unit <- carry_within(as.numeric(psu), pid, as.numeric(wave))
  if_else(is.na(unit), NA_character_, as.character(unit))
})

local({
  w <- as.numeric(wave)
  first <- stats::ave(w, pid, FUN = min)
  sprintf("%.0f", stats::ave(ifelse(w == first, fid, NA), pid, FUN = function(z) z[!is.na(z)][1]))
})

local({
  code <- carry_within(as.numeric(ethnicity_code), pid, as.numeric(wave))
  case_when(is.na(code) ~ "Unknown", code == 1 ~ "Non-minority", .default = "Minority")
})

local({
  low <- stats::ave(household_income_pc, wave, FUN = function(x) stats::quantile(x, 0.4, na.rm = TRUE))
  high <- stats::ave(household_income_pc, wave, FUN = function(x) stats::quantile(x, 0.6, na.rm = TRUE))
  case_when(
    is.na(household_income_pc) ~ "Unknown",
    household_income_pc <= low ~ "Low",
    household_income_pc <= high ~ "Medium",
    .default = "High"
  )
})

local({
  amount <- coalesce(
    if_else(as.numeric(tv_restrict_2010) %in% 1:5, 5 - as.numeric(tv_restrict_2010), NA_real_),
    if_else(as.numeric(tv_restrict) %in% 1:5, 5 - as.numeric(tv_restrict), NA_real_),
    if_else(as.numeric(tv_restrict_2018) %in% 1:5, as.numeric(tv_restrict_2018) - 1, NA_real_)
  )
  types <- coalesce(
    if_else(as.numeric(tv_types_restrict_2010) %in% 1:5, 5 - as.numeric(tv_types_restrict_2010), NA_real_),
    if_else(as.numeric(tv_types_restrict) %in% 1:5, 5 - as.numeric(tv_types_restrict), NA_real_),
    if_else(as.numeric(tv_types_restrict_2018) %in% 1:5, as.numeric(tv_types_restrict_2018) - 1, NA_real_)
  )
  (amount + types) / 2
})

local({
  relation <- as.numeric(proxy_respondent_relation)
  mother <- as.numeric(mother_tv_week_hours)
  father <- as.numeric(father_tv_week_hours)
  case_when(relation == 1 & mother >= 0 ~ mother / 7, relation == 2 & father >= 0 ~ father / 7, .default = NA_real_)
})

local({
  stage <- coalesce(as.numeric(school_stage), as.numeric(school_stage_2010) + 1)
  if_else(stage %in% c(3, 4), "Not tracked", "Unknown")
})

local({
  asked <- as.logical(stats::ave(!is.na(internet_pc_day_mins_self), wave, FUN = any))
  coalesce(as.numeric(internet_pc_day_mins_self) / 60, if_else(asked & as.numeric(internet_pc_user) == 0, 0, NA_real_))
})

local({
  asked <- as.logical(stats::ave(!is.na(internet_mobile_day_mins_self), wave, FUN = any))
  coalesce(
    as.numeric(internet_mobile_day_mins_self) / 60,
    if_else(asked & as.numeric(internet_mobile_user) == 0, 0, NA_real_)
  )
})

local({
  items <- sapply(list(ext_argue, ext_attention, ext_distracted, ext_homework, ext_gossip, ext_fight), as.numeric)
  items[!(items %in% 1:5)] <- NA
  rowSums(items) / 6
})

local({
  items <- sapply(
    list(cesd_depressed, cesd_effort, cesd_sleep, cesd_happy, lonely, cesd_enjoyed, sad, cesd_notgoing),
    as.numeric
  )
  answered <- rowSums(items >= 1 & items <= 4, na.rm = TRUE)
  if_else(answered >= 4, as.numeric(cesd20) - 20, NA_real_)
})

local({
  items <- sapply(
    list(cesd_depressed, cesd_effort, cesd_sleep, cesd_happy, lonely, cesd_enjoyed, sad, cesd_notgoing),
    as.numeric
  )
  answered <- rowSums(items >= 1 & items <= 4, na.rm = TRUE)
  if_else(answered >= 4, as.numeric(cesd20) - 20, NA_real_)
})

local({
  self <- (as.numeric(child_weight_jin_self) / 2) / (as.numeric(child_height_cm_self) / 100)^2
  parent <- (as.numeric(child_weight_jin_parent) / 2) / (as.numeric(child_height_cm_parent) / 100)^2
  coalesce(self, parent)
})

local({
  self <- (as.numeric(child_weight_jin_self) / 2) / (as.numeric(child_height_cm_self) / 100)^2
  parent <- (as.numeric(child_weight_jin_parent) / 2) / (as.numeric(child_height_cm_parent) / 100)^2
  case_when(!is.na(self) ~ "Self-reported", !is.na(parent) ~ "Parent-reported", .default = NA_character_)
})
